// Interpreta a resposta da IA — nunca lanca excecao, falha vira situacaoNaoMapeada
// (regra geral de seguranca, secao 3.2 item 6: nunca adivinhar, sempre alertar).
function parseRespostaIA(textoResposta) {
  try {
    const obj = JSON.parse(textoResposta);
    if (!obj || !obj.tipoLinha) return { situacaoNaoMapeada: 'Resposta da IA sem tipoLinha: ' + String(textoResposta).slice(0,300) };
    return obj;
  } catch (e) {
    return { situacaoNaoMapeada: 'Resposta da IA nao e JSON valido: ' + String(textoResposta).slice(0,300) };
  }
}

const item = $input.first();
const textoResposta = item.json.content && item.json.content[0] ? item.json.content[0].text : '';
const resultado = parseRespostaIA(textoResposta);
return [{ json: { ...$('IF — Contrato liberado?').item.json, ...resultado } }];

// Monta o e-mail de pedido pra caso COLABORADOR (secoes 3.2, 3.3, 3.4).
// dados de tipoLinha/periodo/tipoEmissao/cargo/nomeColaborador ja vieram da IA (node anterior).

const MESES_ABREV_PT = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const MARCADOR_PROJETO = { REUNION: 'REUNION - PEDIDO DE NOTAS', SOFT_PRE: 'SOFT PRE - PEDIDO NOTAS', AREP: 'AREP - PEDIDO DE NOTAS' };
const TOMADOR_HTML = 'Tomador<br>\nBOXFISH PRODUTORA DE PROGRAMAS TELEVISIVOS, INTERNET E FILMES PUBLICITÁRIOS LTDA.<br>\nEndereço: Rua Butantã, 194, sala 24, Pinheiros.<br>\nCEP 05.424-000 - São Paulo, SP<br>\nCNPJ: 14.788.649/0001-23<br>\nIM: 4.436.095-9<br>\nIE: ISENTA';
const AVISO_HTML = '<span style="background-color:#FFFF00;">"Os dados bancários considerados para pagamento são os que estão cadastrados.<br>\nO cadastro é feito baseado nas informações cedidas pelo contratado através do preenchimento de ficha cadastral da Box.<br>\nQualquer alteração bancária ou mudança na forma de pagamento deve ser notificada por e-mail pelo contratado e se faz necessário atualização da ficha cadastral e envio prévio ao responsável financeiro do projeto."</span>';

function formatarDataBR(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear(); }
function formatarDataCurta(d) { return String(d.getDate()).padStart(2,'0') + '.' + String(d.getMonth()+1).padStart(2,'0'); }
function montarRefAssuntoColaborador(tipoEmissao, dataEnvio, parcela) {
  if (tipoEmissao === 'JOB') return parcela ? ('REF. JOB (' + parcela + ')') : 'REF. JOB';
  if (tipoEmissao === 'DIARIA') return 'REF. DIÁRIA';
  if (tipoEmissao === 'PACOTE') return 'REF. PACOTE';
  return 'REF. ' + MESES_ABREV_PT[dataEnvio.getMonth()]; // mes do ENVIO, nao do vencimento (evidencia: exemplo Media Arts, secao 3.2.1)
}
function montarPeriodoTexto(periodo, tipoEmissao) {
  if (!periodo) return '';
  const PALAVRA_CHAVE = { JOB: 'JOB', DIARIA: 'DIÁRIA', PACOTE: 'PACOTE' };
  const palavra = PALAVRA_CHAVE[tipoEmissao];
  return palavra ? (periodo + ' (' + palavra + ')') : periodo;
}
function montarCorpoEmailColaborador(p) {
  const valorFmt = p.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return 'Olá ' + p.primeiroNome + '! Tudo bem?<br><br>\n' +
    'Seguem as instruções para a emissão da sua nota fiscal que deverá ser enviada até o dia ' + formatarDataBR(p.dataEnvio) + ' com vencimento em ' + formatarDataBR(p.dataVencimento) + '.<br><br>\n' +
    TOMADOR_HTML + '<br><br>\n' +
    '1- Emitir nota fiscal no valor de R$ ' + valorFmt + ' com os dados abaixo no corpo da nota:<br>\n' +
    'Ref. "' + p.textoRef + '"<br>\n' +
    'Serviço Prestado como: ' + p.cargo + '<br>\n' +
    'Colaborador: ' + p.nomeColaborador + '<br>\n' +
    (p.periodoTexto ? ('Período de ' + p.periodoTexto + '<br>\n') : '') +
    'Dados bancários:<br>\nChave pix:<br>\n---------------------------------------------------------------------<br><br>\n' +
    'Importante: Peço a gentileza de enviar a sua nota nestes e-mails:<br>\nfinanceiro@novorealitybox.com<br>\nfinanceiro1@novorealitybox.com<br><br>\n' +
    AVISO_HTML + '<br><br>\nMuito obrigada! Beijo 🌷';
}
function ehModoAutomatico(config) { return config && config.modo === 'automatico'; }
function decidirAcaoEnvio(gatilho, modoAutomatico) {
  if (!modoAutomatico) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  if (gatilho === 'SOLICITAR') return { acaoGmail: 'enviar_direto', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
  return { acaoGmail: 'agendar_envio', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
}

const hoje = new Date();
const saida = [];

for (const item of $input.all()) {
  const d = item.json;
  const cargo = d.cargo === 'FALTA INFORMAÇÃO' || d.cargo === 'FALTA INFORMACAO' ? 'FALTA INFORMAÇÃO' : (d.cargo || d.nota.colunaJ);
  const nomeColaborador = d.nomeColaborador === 'FALTA INFORMAÇÃO' || d.nomeColaborador === 'FALTA INFORMACAO' ? 'FALTA INFORMAÇÃO' : (d.nomeColaborador || d.nota.colunaH);
  const temLacuna = cargo === 'FALTA INFORMAÇÃO' || nomeColaborador === 'FALTA INFORMAÇÃO';
  const primeiroNome = (nomeColaborador === 'FALTA INFORMAÇÃO' ? 'Colaborador' : nomeColaborador).split(' ')[0];

  const dataVencimento = new Date(d.nota.colunaG);
  const dataBase = d.gatilho === 'PROGRAMAR_ATE' ? new Date(d.dataProgramarAte) : hoje;
  const dataEnvio = d.gatilho === 'PROGRAMAR_ATE' ? (function(){ const dd = new Date(dataBase); dd.setDate(dd.getDate()+5); return dd; })() : dataBase;

  const tipoEmissao = d.tipoEmissao || 'NF_NORMAL';
  const refAssunto = montarRefAssuntoColaborador(tipoEmissao, dataEnvio, d.parcela);
  const apelidoAtual = (d.apelidos && d.apelidos[d.nota.projetoId] && d.apelidos[d.nota.projetoId].length) ? d.apelidos[d.nota.projetoId][d.apelidos[d.nota.projetoId].length - 1] : d.perfil.prefixo_assunto_pedido;

  const periodoTexto = montarPeriodoTexto(d.periodo, tipoEmissao);
  const corpo = montarCorpoEmailColaborador({ primeiroNome, dataEnvio, dataVencimento, textoRef: d.perfil.texto_ref, valor: d.nota.colunaK, cargo, nomeColaborador, periodoTexto });
  const assunto = apelidoAtual + ' | EMISSÃO DE NF | ' + refAssunto + ' (ENVIAR ATÉ ' + formatarDataCurta(dataEnvio) + ') | ' + nomeColaborador;

  const decisao = decidirAcaoEnvio(d.gatilho, ehModoAutomatico(d.config));

  saida.push({ json: {
    ...d,
    acao: decisao.acaoGmail,
    atualizarColunaL: decisao.atualizarColunaL,
    novoValorColunaL: decisao.novoValorColunaL,
    emailDestino: d.nota.colunaR,
    assunto,
    corpoHtml: corpo,
    marcadores: ['IA', MARCADOR_PROJETO[d.nota.projetoId]],
    temLacunaInformacao: temLacuna,
  } });
}

return saida;

// Agrupa linhas FORNECEDOR (mesmo projeto+fornecedor+vencimento) e monta 1 e-mail
// multi-bloco por grupo (secao 3.2.1). Roda 1x pra TODOS os itens fornecedor da execucao
// (mode = runOnceForAllItems).

const MESES_ABREV_PT = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const MARCADOR_PROJETO = { REUNION: 'REUNION - PEDIDO DE NOTAS', SOFT_PRE: 'SOFT PRE - PEDIDO NOTAS', AREP: 'AREP - PEDIDO DE NOTAS' };
const TOMADOR_HTML = 'Tomador<br>\nBOXFISH PRODUTORA DE PROGRAMAS TELEVISIVOS, INTERNET E FILMES PUBLICITÁRIOS LTDA.<br>\nEndereço: Rua Butantã, 194, sala 24, Pinheiros.<br>\nCEP 05.424-000 - São Paulo, SP<br>\nCNPJ: 14.788.649/0001-23<br>\nIM: 4.436.095-9<br>\nIE: ISENTA';
const AVISO_HTML = '<span style="background-color:#FFFF00;">"Os dados bancários considerados para pagamento são os que estão cadastrados.<br>\nO cadastro é feito baseado nas informações cedidas pelo contratado através do preenchimento de ficha cadastral da Box.<br>\nQualquer alteração bancária ou mudança na forma de pagamento deve ser notificada por e-mail pelo contratado e se faz necessário atualização da ficha cadastral e envio prévio ao responsável financeiro do projeto."</span>';

function normalizar(t) { return t ? String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim() : ''; }
function formatarDataBR(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear(); }
function formatarDataCurta(d) { return String(d.getDate()).padStart(2,'0') + '.' + String(d.getMonth()+1).padStart(2,'0'); }
function ehModoAutomatico(config) { return config && config.modo === 'automatico'; }
function decidirAcaoEnvio(gatilho, modoAutomatico) {
  if (!modoAutomatico) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  if (gatilho === 'SOLICITAR') return { acaoGmail: 'enviar_direto', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
  return { acaoGmail: 'agendar_envio', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
}

function agruparLinhasFornecedor(itens) {
  const grupos = new Map();
  for (const item of itens) {
    const chave = [item.nota.projetoId, normalizar(item.nota.colunaH), item.nota.colunaG].join('|');
    if (!grupos.has(chave)) grupos.set(chave, []);
    grupos.get(chave).push(item);
  }
  return Array.from(grupos.values());
}
function ordenarBlocosGrupo(grupo) {
  const recibos = grupo.filter((i) => i.documentoLinha === 'RECIBO');
  const notas = grupo.filter((i) => i.documentoLinha === 'NOTA_FISCAL');
  const semClassificacao = grupo.filter((i) => i.documentoLinha !== 'RECIBO' && i.documentoLinha !== 'NOTA_FISCAL');
  return { blocosOrdenados: [...recibos, ...notas], semClassificacao };
}
function montarBlocoRecibo(numero, item, textoRef) {
  const valorFmt = item.nota.colunaK.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return numero + '- Emitir RECIBO no valor de R$ ' + valorFmt + ' com os dados abaixo no corpo do recibo:<br>\n' +
    'Ref. "' + textoRef + '"<br>\nFornecedor: ' + item.nota.colunaH + '<br>\n' +
    'Período de ' + (item.periodo || '') + ' - ' + item.descricaoServicoOuLocacao + '<br>\n' +
    'Dados bancários:<br>\nChave pix:<br>\n---------------------------------------------------------------------';
}
function montarBlocoNotaFiscal(numero, item, textoRef) {
  const valorFmt = item.nota.colunaK.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return numero + '- Emitir NOTA FISCAL no valor de R$ ' + valorFmt + ' com os dados abaixo no corpo da nota:<br>\n' +
    'Ref. "' + textoRef + '"<br>\nFornecedor: ' + item.nota.colunaH + '<br>\n' +
    'Serviço Prestado: ' + item.descricaoServicoOuLocacao + '<br>\n' +
    'Período de ' + (item.periodo || '') + '<br>\n' +
    'Dados bancários:<br>\nChave pix:<br>\n---------------------------------------------------------------------';
}
function montarCorpoEmailFornecedor({ blocosOrdenados, temNotaFiscal, dataEnvio, dataVencimento, textoRef }) {
  const abertura = temNotaFiscal
    ? 'Seguem as instruções para a emissão do RECIBO e da NOTA FISCAL que deverão ser enviadas até o dia ' + formatarDataBR(dataEnvio) + ' com vencimento em ' + formatarDataBR(dataVencimento) + ':'
    : 'Seguem as instruções para a emissão da sua FATURA que deverá ser enviada até o dia ' + formatarDataBR(dataEnvio) + ' com vencimento em ' + formatarDataBR(dataVencimento) + '.';
  const blocosHtml = blocosOrdenados.map((item, idx) => item.documentoLinha === 'RECIBO' ? montarBlocoRecibo(idx+1, item, textoRef) : montarBlocoNotaFiscal(idx+1, item, textoRef)).join('<br><br>\n');
  return 'Olá! Tudo bem?<br><br>\n' + abertura + '<br><br>\n' + TOMADOR_HTML + '<br><br>\n' + blocosHtml + '<br><br>\n' +
    'Importante: Peço a gentileza de enviar a sua nota nestes e-mails:<br>\nfinanceiro@novorealitybox.com<br>\nfinanceiro1@novorealitybox.com<br><br>\n' +
    AVISO_HTML + '<br><br>\nMuito obrigada! Beijo 🌷';
}
function montarAssuntoFornecedor({ apelidoAtual, temNotaFiscal, parcela, dataEnvio, fornecedor }) {
  const mes = MESES_ABREV_PT[dataEnvio.getMonth()]; // mes do ENVIO (evidencia: exemplo Media Arts, secao 3.2.1)
  const palavraDocumento = temNotaFiscal ? 'EMISSÃO DE FATURA' : 'EMISSÃO DE RECIBO';
  const ref = temNotaFiscal ? ('REF. LOCAÇÃO E SERVIÇOS - ' + mes) : ('REF. LOCAÇÃO - ' + mes + (parcela ? (' - ' + parcela) : ''));
  return apelidoAtual + ' | ' + palavraDocumento + ' | ' + ref + ' | (ENVIAR ATÉ ' + formatarDataCurta(dataEnvio) + ') | ' + fornecedor;
}

const hoje = new Date();
const itens = $input.all().map((i) => i.json);
const grupos = agruparLinhasFornecedor(itens);
const saida = [];

for (const grupo of grupos) {
  const { blocosOrdenados, semClassificacao } = ordenarBlocosGrupo(grupo);

  if (semClassificacao.length > 0) {
    // Regra de seguranca (secao 3.2.1): nao adivinhar RECIBO vs NOTA_FISCAL sem marcacao clara.
    saida.push({ json: { ...semClassificacao[0], acao: 'alerta_situacao_nao_mapeada', situacaoNaoMapeada: 'Não foi possível classificar RECIBO/NOTA_FISCAL para ' + semClassificacao.length + ' linha(s) do fornecedor ' + grupo[0].nota.colunaH } });
    continue;
  }
  if (blocosOrdenados.length === 0) continue;

  const primeiro = blocosOrdenados[0];
  const temNotaFiscal = blocosOrdenados.some((b) => b.documentoLinha === 'NOTA_FISCAL');
  const dataVencimento = new Date(primeiro.nota.colunaG);
  const dataBase = primeiro.gatilho === 'PROGRAMAR_ATE' ? new Date(primeiro.dataProgramarAte) : hoje;
  const dataEnvio = primeiro.gatilho === 'PROGRAMAR_ATE' ? (function(){ const dd = new Date(dataBase); dd.setDate(dd.getDate()+5); return dd; })() : dataBase;
  const apelidoAtual = (primeiro.apelidos && primeiro.apelidos[primeiro.nota.projetoId] && primeiro.apelidos[primeiro.nota.projetoId].length) ? primeiro.apelidos[primeiro.nota.projetoId][primeiro.apelidos[primeiro.nota.projetoId].length - 1] : primeiro.perfil.prefixo_assunto_pedido;

  const corpo = montarCorpoEmailFornecedor({ blocosOrdenados, temNotaFiscal, dataEnvio, dataVencimento, textoRef: primeiro.perfil.texto_ref });
  const assunto = montarAssuntoFornecedor({ apelidoAtual, temNotaFiscal, parcela: primeiro.parcela, dataEnvio, fornecedor: primeiro.nota.colunaH });
  const decisao = decidirAcaoEnvio(primeiro.gatilho, ehModoAutomatico(primeiro.config));

  saida.push({ json: {
    ...primeiro,
    acao: decisao.acaoGmail,
    atualizarColunaL: decisao.atualizarColunaL,
    novoValorColunaL: decisao.novoValorColunaL,
    // ASSUNÇÃO: e-mail de contato do fornecedor vem da mesma coluna R ("E-mail do colaborador")
    // da 1a linha do grupo — a planilha nao documenta uma coluna separada pra e-mail de fornecedor.
    emailDestino: primeiro.nota.colunaR,
    assunto,
    corpoHtml: corpo,
    marcadores: ['IA', MARCADOR_PROJETO[primeiro.nota.projetoId]],
    linhasAfetadas: blocosOrdenados.map((b) => ({ projetoId: b.nota.projetoId, linha: b.nota.linha, atualizarColunaNPara: b.atualizarColunaNPara })),
  } });
}

return saida;

// Consolida: (a) mudancas de coluna N/L a escrever no Box, (b) novo cobrancas.json,
// (c) resumo pro relatorio (incl. lacunas de informacao e alertas de situacao nao mapeada).
// Suporta tanto itens de 1 linha (colaborador/cobranca/pendente) quanto itens de
// GRUPO fornecedor (varias linhas por item, campo linhasAfetadas — secao 3.2.1).

const itens = $input.all().map((i) => i.json);

const mudancasColunaN = [];
const mudancasColunaL = [];

for (const d of itens) {
  if (Array.isArray(d.linhasAfetadas)) {
    for (const la of d.linhasAfetadas) {
      if (la.atualizarColunaNPara) mudancasColunaN.push({ projetoId: la.projetoId, linha: la.linha, valor: la.atualizarColunaNPara });
      if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: la.projetoId, linha: la.linha, valor: d.novoValorColunaL });
    }
    continue;
  }
  if (d.atualizarColunaNPara) mudancasColunaN.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.atualizarColunaNPara });
  if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.novoValorColunaL });
}

const cobrancasAtualizadas = { ...(itens[0] ? itens[0].cobrancas : {}) };
for (const d of itens) {
  if (d.chaveCobranca && d.novoEstadoCobranca) cobrancasAtualizadas[d.chaveCobranca] = d.novoEstadoCobranca;
}

const alertasEncerramento = itens.filter((d) => d.acao === 'encerrar_sem_resposta');
const alertasSituacaoNaoMapeada = itens.filter((d) => d.acao === 'alerta_situacao_nao_mapeada');
const rascunhosCriados = itens.filter((d) => d.acao === 'criar_rascunho' || d.acao === 'cobrar_rascunho');
const enviosDiretos = itens.filter((d) => d.acao === 'enviar_direto' || d.acao === 'cobrar_enviar');
const pendentesContrato = itens.filter((d) => d.acao === 'pendente_contrato');
const comLacunaInformacao = itens.filter((d) => d.temLacunaInformacao);

return [{ json: {
  mudancasColunaN, mudancasColunaL, cobrancasAtualizadas,
  resumo: {
    rascunhosCriados: rascunhosCriados.length,
    enviosDiretos: enviosDiretos.length,
    pendentesContrato: pendentesContrato.length,
    comLacunaInformacao: comLacunaInformacao.length,
    alertasSituacaoNaoMapeada: alertasSituacaoNaoMapeada.length,
    alertasEncerramento: alertasEncerramento.map((a) => ({ colaboradorOuFornecedor: a.nomeColaborador || a.nota.colunaH, projetoId: a.nota.projetoId })),
  },
} }];

// Aplica as mudanças de coluna N e L em memória (exceljs) e prepara o binário pra upload.
const ExcelJS = require('exceljs');

const mudancasN = $('Consolidar mudanças e cobrancas.json').first().json.mudancasColunaN;
const mudancasL = $('Consolidar mudanças e cobrancas.json').first().json.mudancasColunaL;

const item = $input.first();
const buffer = Buffer.from(item.binary.data.data, 'base64');
const wb = new ExcelJS.Workbook();
await wb.xlsx.load(buffer);
const ws = wb.getWorksheet('Notas') || wb.worksheets[0];

for (const m of mudancasN) {
  ws.getCell('N' + m.linha).value = m.valor;
}
for (const m of mudancasL) {
  ws.getCell('L' + m.linha).value = m.valor;
}

const novoBuffer = await wb.xlsx.writeBuffer();
return [{
  json: {},
  binary: { data: { data: Buffer.from(novoBuffer).toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: 'cost_report_atualizado.xlsx' } },
}];
